/* Content for the anatomy guide and reference sheets. Facts cross-checked against
   standard anatomy references; pearls emphasize board-relevant associations. */
const LAYERS = [
  { k: "bone", n: "Skeleton", c: "#D9C9A3" },
  { k: "organ", n: "Organs", c: "#E69E8D" },
  { k: "muscle", n: "Muscles", c: "#B8463F" },
  { k: "artery", n: "Arteries", c: "#D2352E" },
  { k: "vein", n: "Veins", c: "#3262C8" },
  { k: "nerve", n: "Nerves", c: "#E0AE18" },
  { k: "lymph", n: "Lymphatics", c: "#2C9C66" },
];

const INFO = {
  /* ---------- Skeleton ---------- */
  skull_frontal: { n: "Frontal bone", L: "bone", d: "Forms the forehead and the roofs of the orbits. Contains the frontal sinuses.", p: "Frontal sinusitis can spread to bone, causing osteomyelitis with a subperiosteal abscess (Pott puffy tumor)." },
  skull_parietal: { n: "Parietal bone", L: "bone", d: "Paired bones forming the roof and upper sides of the cranium; they meet at the sagittal suture.", p: "The pterion, where the frontal, parietal, temporal, and sphenoid bones meet, overlies the middle meningeal artery. A blow here can cause an epidural hematoma with a lucid interval." },
  skull_temporal: { n: "Temporal bone", L: "bone", d: "Houses the middle and inner ear (including the ossicles) and forms the lower side of the skull. Includes the mastoid and petrous parts.", p: "Basilar skull fracture signs: mastoid bruising (Battle sign), periorbital bruising (raccoon eyes), hemotympanum, and CSF otorrhea or rhinorrhea." },
  skull_zygomatic: { n: "Zygomatic bone", L: "bone", d: "The cheekbone. Forms the lateral orbital wall and floor and part of the zygomatic arch.", p: "Zygomaticomaxillary complex (tripod) fractures can injure the infraorbital nerve (V2), causing numbness of the cheek and upper lip." },
  orbit: { n: "Orbit", L: "bone", d: "Bony socket formed by seven bones: frontal, zygomatic, maxilla, lacrimal, ethmoid, sphenoid, and palatine.", p: "Orbital floor (blowout) fracture can trap the inferior rectus: impaired upward gaze, vertical diplopia, and infraorbital numbness." },
  skull_maxilla: { n: "Maxilla", L: "bone", d: "Upper jaw. Holds the upper teeth, forms most of the hard palate, and contains the maxillary sinus, the largest paranasal sinus.", p: "Le Fort fractures: I (horizontal, separates the palate), II (pyramidal, through the nasal bridge), III (craniofacial disjunction)." },
  skull_nasal: { n: "Nasal bone", L: "bone", d: "Paired small bones forming the bridge of the nose.", p: "The most commonly fractured facial bone. Always look for a septal hematoma: it needs drainage to prevent septal necrosis and saddle-nose deformity." },
  skull_mandible: { n: "Mandible", L: "bone", d: "Lower jaw; the only movable skull bone, articulating at the temporomandibular joints.", p: "Because the mandible forms a ring with the skull base, it often fractures in two places." },
  hyoid: { n: "Hyoid bone", L: "bone", d: "U-shaped bone at about C3 that anchors the tongue and laryngeal muscles. It does not articulate with any other bone.", p: "A hyoid fracture at autopsy suggests manual strangulation." },
  cervical: { n: "Cervical vertebrae (C1–C7)", L: "bone", d: "Seven neck vertebrae. C1 (atlas) supports the skull; C2 (axis) has the dens. Transverse foramina carry the vertebral arteries (typically entering at C6).", p: "Jefferson fracture: C1 burst from axial load. Hangman fracture: bilateral C2 pars fracture from hyperextension. Down syndrome and rheumatoid arthritis predispose to atlantoaxial instability." },
  thoracicv: { n: "Thoracic vertebrae (T1–T12)", L: "bone", d: "Twelve vertebrae that articulate with the ribs; mostly hidden behind the sternum in this view.", p: "Osteoporotic compression fractures cluster in the thoracolumbar spine. Tuberculous spondylitis (Pott disease) classically affects the lower thoracic spine." },
  lumbar: { n: "Lumbar vertebrae (L1–L5)", L: "bone", d: "Five large vertebrae bearing most of the body's weight.", p: "The adult spinal cord ends at L1–L2, so lumbar puncture is done at L3–L4 or L4–L5 (a line between the iliac crests crosses about L4). Disc herniations are most common at L4–L5 and L5–S1." },
  sacrum: { n: "Sacrum", L: "bone", d: "Five fused vertebrae forming the back of the pelvis and articulating with the hip bones at the sacroiliac joints.", p: "Sacral roots S2–S4 control bladder, bowel, and sexual function. Cauda equina syndrome (saddle anesthesia, urinary retention, decreased anal tone) needs emergent MRI and decompression." },
  coccyx: { n: "Coccyx", L: "bone", d: "The tailbone: three to five small fused vertebrae.", p: "Coccydynia often follows a fall or childbirth. Pilonidal disease occurs in the skin over the sacrococcygeal region." },
  scapula: { n: "Scapula", L: "bone", d: "Shoulder blade, mostly behind the rib cage. Its glenoid fossa forms the shoulder joint with the humeral head.", p: "Winged scapula = long thoracic nerve injury (serratus anterior), classically after mastectomy with axillary dissection. A scapular fracture implies high-energy trauma; look for associated injuries." },
  ribs: { n: "Ribs", L: "bone", d: "Twelve pairs. Ribs 1–7 are true ribs (attach directly to the sternum), 8–10 are false ribs, and 11–12 are floating ribs.", p: "The intercostal vein, artery, and nerve run in the groove under each rib, so chest tubes and thoracentesis go just over the top of a rib. Lower rib fractures (9–12) should raise concern for spleen or liver injury." },
  costal: { n: "Costal cartilages", L: "bone", d: "Hyaline cartilage connecting the ribs to the sternum, giving the chest wall flexibility for breathing.", p: "Costochondritis causes reproducible chest wall tenderness. In Tietze syndrome there is visible swelling of the costal cartilages." },
  sternum: { n: "Sternum", L: "bone", d: "Breastbone: manubrium, body, and xiphoid process. The sternal angle (of Louis) marks the 2nd rib and the T4–T5 level.", p: "The sternal angle is where the trachea bifurcates and the aortic arch begins and ends. A sternal fracture should prompt evaluation for blunt cardiac injury (ECG, troponin)." },
  clavicle: { n: "Clavicle", L: "bone", d: "Collarbone connecting the sternum to the scapula (acromion); the only bony attachment of the arm to the trunk.", p: "Most commonly fractured bone in newborns (often with shoulder dystocia) and very common in children. Most fractures occur in the middle third." },
  humerus: { n: "Humerus", L: "bone", d: "Upper arm bone, from the shoulder to the elbow.", p: "Classic nerve associations: surgical neck fracture → axillary nerve (and posterior circumflex humeral artery); midshaft → radial nerve (wrist drop); supracondylar (children) → median nerve and brachial artery; medial epicondyle → ulnar nerve." },
  radius: { n: "Radius", L: "bone", d: "Lateral (thumb-side) forearm bone; rotates around the ulna for pronation and supination.", p: "Colles fracture: distal radius with dorsal displacement (fall on outstretched hand). Galeazzi: radial shaft fracture with distal radioulnar joint dislocation. Nursemaid's elbow: radial head subluxation in a toddler pulled by the arm." },
  ulna: { n: "Ulna", L: "bone", d: "Medial (little-finger-side) forearm bone; its olecranon forms the point of the elbow.", p: "Monteggia: proximal ulnar fracture with radial head dislocation (may injure the posterior interosseous nerve). Nightstick fracture: isolated ulnar shaft fracture from a defensive blow." },
  carpals: { n: "Carpal bones", L: "bone", d: "Eight wrist bones in two rows: scaphoid, lunate, triquetrum, pisiform, trapezium, trapezoid, capitate, hamate.", p: "Scaphoid is the most fractured carpal bone (snuffbox tenderness); its retrograde blood supply puts the proximal pole at risk of avascular necrosis, so treat suspected fractures even with a normal first x-ray. Lunate dislocation can compress the median nerve." },
  metacarpals: { n: "Metacarpals", L: "bone", d: "Five bones of the palm.", p: "Boxer's fracture: 5th metacarpal neck. Bennett fracture: intra-articular fracture at the base of the 1st metacarpal. A 'fight bite' over a knuckle is an open joint injury until proven otherwise." },
  hand_phalanges: { n: "Phalanges of the hand", L: "bone", d: "Fourteen per hand: two in the thumb, three in each finger.", p: "Mallet finger: extensor tendon avulsion at the DIP joint. Jersey finger: flexor digitorum profundus avulsion, usually the ring finger." },
  hipbone: { n: "Hip bone (os coxae)", L: "bone", d: "Ilium, ischium, and pubis fused at the acetabulum. Two hip bones plus the sacrum form the pelvis.", p: "Pelvic fractures can bleed massively (venous plexus and internal iliac branches); apply a pelvic binder. Blood at the urethral meatus means retrograde urethrogram before placing a Foley catheter." },
  femur: { n: "Femur", L: "bone", d: "Thigh bone; the longest and strongest bone in the body.", p: "Femoral neck fracture (shortened, externally rotated leg) risks avascular necrosis via the medial circumflex femoral artery. Shaft fractures can lose 1–1.5 L of blood and cause fat embolism (hypoxemia, confusion, petechiae)." },
  patella: { n: "Patella", L: "bone", d: "Kneecap; the largest sesamoid bone, lying within the quadriceps tendon.", p: "Patellar dislocation is almost always lateral. A displaced transverse fracture disrupts the extensor mechanism: the patient cannot do a straight-leg raise." },
  tibia: { n: "Tibia", L: "bone", d: "Shinbone; the main weight-bearing bone of the leg. Its medial malleolus forms the inner ankle.", p: "Tibial shaft fractures carry the highest risk of compartment syndrome: pain out of proportion and pain with passive stretch mean urgent fasciotomy. Osgood–Schlatter disease is tibial tubercle apophysitis in adolescent athletes." },
  fibula: { n: "Fibula", L: "bone", d: "Thin lateral leg bone, mainly for muscle attachment; its lateral malleolus forms the outer ankle.", p: "Fibular neck fracture can injure the common fibular nerve, causing foot drop. Maisonneuve fracture: proximal fibula fracture with a medial ankle/syndesmosis injury." },
  tarsals: { n: "Tarsal bones", L: "bone", d: "Seven per foot: talus, calcaneus, navicular, cuboid, and three cuneiforms.", p: "Calcaneus is the most fractured tarsal; after a fall from height, check the lumbar spine too. Talar neck fractures risk avascular necrosis." },
  metatarsals: { n: "Metatarsals", L: "bone", d: "Five long bones of the midfoot.", p: "Jones fracture (5th metatarsal metaphyseal–diaphyseal junction) heals poorly. A 2nd metatarsal stress fracture is the classic 'march fracture.'" },
  foot_phalanges: { n: "Phalanges of the foot", L: "bone", d: "Fourteen per foot: two in the great toe, three in each other toe.", p: "The 1st metatarsophalangeal joint is the classic site of gout (podagra) and of hallux valgus (bunion)." },

  /* ---------- Organs ---------- */
  brain: { n: "Brain", L: "organ", d: "Cerebrum, cerebellum, and brainstem. About 2% of body weight.", p: "The brain uses roughly 20% of the body's oxygen at rest, which is why a few minutes of global ischemia causes irreversible injury (watershed zones and hippocampus are most vulnerable)." },
  eye: { n: "Eye", L: "organ", d: "Globe within the orbit; moved by six extraocular muscles supplied by CN III, IV, and VI.", p: "Acute angle-closure glaucoma: painful red eye, fixed mid-dilated pupil, halos, nausea. It is an emergency." },
  esophagus: { n: "Esophagus", L: "organ", d: "Muscular tube (~25 cm) from C6 to the stomach, passing through the diaphragm at T10. Upper third skeletal muscle, lower third smooth muscle.", p: "Mallory–Weiss tear = mucosal tear after retching; Boerhaave syndrome = full-thickness rupture, usually distal left posterolateral wall, with mediastinitis." },
  trachea: { n: "Trachea and main bronchi", L: "organ", d: "Airway from C6 to the carina at T4–T5, held open by C-shaped cartilage rings.", p: "The right main bronchus is wider, shorter, and more vertical, so aspirated objects usually go right (right lower lobe when upright)." },
  thyroid: { n: "Thyroid gland", L: "organ", d: "Butterfly-shaped gland in front of the trachea; the isthmus lies over tracheal rings 2–4. Four parathyroid glands sit on its back.", p: "Thyroidectomy risks: recurrent laryngeal nerve injury (hoarseness) and hypocalcemia from parathyroid removal or devascularization." },
  lung_r: { n: "Right lung", L: "organ", d: "Three lobes (upper, middle, lower), separated by the horizontal and oblique fissures.", p: "Aspiration while upright goes to the right lower lobe; while supine, to the posterior segment of the right upper lobe or superior segment of the right lower lobe. Lung apices rise above the clavicle (Pancoast tumor → Horner syndrome)." },
  lung_l: { n: "Left lung", L: "organ", d: "Two lobes plus the lingula; the cardiac notch makes room for the heart.", p: "The lingula is the left lung's counterpart to the right middle lobe. Lingular consolidation blurs the left heart border on chest x-ray (silhouette sign)." },
  heart: { n: "Heart", L: "organ", d: "Four-chambered pump in the middle mediastinum; the apex sits at the left 5th intercostal space, midclavicular line.", p: "The right ventricle is the most anterior chamber (most injured in penetrating chest trauma). The left atrium is the most posterior; enlargement can compress the esophagus (dysphagia) or left recurrent laryngeal nerve (hoarseness)." },
  diaphragm: { n: "Diaphragm", L: "organ", d: "Main muscle of breathing, innervated by the phrenic nerve (C3–C5). Openings: IVC at T8, esophagus at T10, aorta at T12.", p: "Diaphragmatic irritation refers pain to the shoulder (Kehr sign with splenic rupture). Mnemonic for the openings: 'I 8 10 Eggs At 12.'" },
  liver: { n: "Liver", L: "organ", d: "Largest internal organ (~1.5 kg). Dual blood supply: portal vein (~75%) and hepatic artery (~25%).", p: "Zone 3 (centrilobular) hepatocytes are most vulnerable to ischemia and to acetaminophen toxicity, because they have the most CYP450 and the least oxygen." },
  gallbladder: { n: "Gallbladder", L: "organ", d: "Stores and concentrates bile; releases it in response to cholecystokinin.", p: "The hepatocystic (Calot) triangle (cystic duct, common hepatic duct, liver edge) contains the cystic artery. Right upper quadrant ultrasound is the first test for suspected cholecystitis." },
  stomach: { n: "Stomach", L: "organ", d: "J-shaped muscular sac in the left upper quadrant; parietal cells secrete acid and intrinsic factor.", p: "Loss of parietal cells (autoimmune gastritis, gastrectomy) means no intrinsic factor and eventual vitamin B12 deficiency." },
  spleen: { n: "Spleen", L: "organ", d: "Lymphoid organ in the left upper quadrant under ribs 9–11; filters blood and removes old red cells.", p: "Most commonly injured organ in blunt abdominal trauma. After splenectomy, vaccinate against encapsulated organisms (S. pneumoniae, H. influenzae type b, N. meningitidis); Howell–Jolly bodies appear on smear." },
  pancreas: { n: "Pancreas", L: "organ", d: "Retroperitoneal gland (except the tail) with exocrine enzymes and endocrine islets; the head sits in the duodenal C-loop.", p: "Pancreatic head cancer: painless jaundice with a palpable, nontender gallbladder (Courvoisier sign). Gallstones and alcohol cause most acute pancreatitis." },
  duodenum: { n: "Duodenum", L: "organ", d: "First part of the small intestine; C-shaped and mostly retroperitoneal. Bile and pancreatic juice enter at the ampulla in the 2nd part.", p: "A posterior duodenal ulcer can erode the gastroduodenal artery and bleed briskly. Obstruction distal to the ampulla causes bilious vomiting." },
  small_intestine: { n: "Jejunum and ileum", L: "organ", d: "Several meters of small intestine where most absorption happens.", p: "The terminal ileum absorbs vitamin B12 and bile acids; Crohn disease or ileal resection causes B12 deficiency and bile-acid diarrhea. Meckel diverticulum follows the 'rule of 2s.'" },
  colon: { n: "Large intestine (colon)", L: "organ", d: "Cecum, ascending, transverse, descending, and sigmoid colon; absorbs water and electrolytes.", p: "Watershed areas (splenic flexure and rectosigmoid junction) are most vulnerable to ischemic colitis. Sigmoid volvulus ('coffee bean' sign) typically affects older adults." },
  appendix: { n: "Appendix", L: "organ", d: "Blind-ended tube off the cecum, rich in lymphoid tissue. McBurney point lies one-third of the way from the right ASIS to the umbilicus.", p: "Appendicitis pain classically starts periumbilical (visceral, T10) and migrates to the right lower quadrant once the parietal peritoneum is irritated." },
  rectum: { n: "Rectum and anal canal", L: "organ", d: "Final segment of the gut, ending at the anus.", p: "The pectinate (dentate) line divides internal hemorrhoids above (painless, visceral innervation) from external hemorrhoids below (painful, somatic innervation)." },
  kidney: { n: "Kidney", L: "organ", d: "Retroperitoneal, about T12–L3; the right kidney sits slightly lower because of the liver.", p: "A horseshoe kidney gets caught under the inferior mesenteric artery. The left renal vein passes between the aorta and SMA, where compression (nutcracker) can cause a left varicocele or hematuria." },
  adrenal: { n: "Adrenal gland", L: "organ", d: "Cortex: zona glomerulosa (aldosterone), fasciculata (cortisol), reticularis (androgens) — 'salt, sugar, sex.' Medulla: catecholamines.", p: "The left adrenal vein drains into the left renal vein; the right drains directly into the IVC. Pheochromocytoma arises from the medulla." },
  ureter: { n: "Ureter", L: "organ", d: "Muscular tube carrying urine from kidney to bladder.", p: "'Water under the bridge': the ureter passes under the uterine artery (and the vas deferens), so it is at risk during hysterectomy. Stones lodge at the ureteropelvic junction, the pelvic brim, and the ureterovesical junction (narrowest)." },
  bladder: { n: "Urinary bladder", L: "organ", d: "Muscular reservoir behind the pubic symphysis; its dome is covered by peritoneum.", p: "Dome rupture (blow to a full bladder) leaks urine intraperitoneally and needs surgical repair; extraperitoneal rupture (often with pelvic fracture) is usually managed with catheter drainage." },
  uterus: { n: "Uterus", L: "organ", d: "Muscular organ where a pregnancy implants and develops.", p: "Leiomyomas (fibroids) are the most common benign uterine tumors. The uterine artery crosses over the ureter near the cervix." },
  uterine_tube: { n: "Uterine (fallopian) tube", L: "organ", d: "Carries the egg from the ovary to the uterus; fertilization usually occurs in the ampulla.", p: "The ampulla is the most common site of ectopic pregnancy. Prior salpingitis (chlamydia, gonorrhea) is a major risk factor." },
  ovary: { n: "Ovary", L: "organ", d: "Produces eggs, estrogen, and progesterone; its vessels run in the suspensory (infundibulopelvic) ligament.", p: "Ovarian torsion presents with sudden unilateral pelvic pain, often with an enlarged ovary or mass. The left ovarian vein drains to the left renal vein, the right to the IVC." },
  testis: { n: "Testis", L: "organ", d: "Produces sperm and testosterone; descends into the scrotum before birth.", p: "Testicular torsion: sudden pain, high-riding testis, absent cremasteric reflex; detorse within about 6 hours. The testis drains to para-aortic nodes, while scrotal skin drains to superficial inguinal nodes." },
  vas_deferens: { n: "Vas deferens", L: "organ", d: "Carries sperm from the epididymis through the inguinal canal to the ejaculatory duct.", p: "The ureter passes under the vas deferens in men ('water under the bridge'). Congenital bilateral absence of the vas is associated with cystic fibrosis." },
  prostate: { n: "Prostate", L: "organ", d: "Gland surrounding the urethra below the bladder; contributes to seminal fluid.", p: "Benign prostatic hyperplasia arises in the transition (periurethral) zone; prostate cancer most often arises in the peripheral zone, which is palpable on rectal exam." },

  /* ---------- Muscles ---------- */
  scm: { n: "Sternocleidomastoid", L: "muscle", d: "Runs from the sternum and clavicle to the mastoid. Turns the head to the opposite side. Innervated by CN XI.", p: "Congenital muscular torticollis tilts the head toward the tight muscle. The triangle between its two heads is a landmark for internal jugular line placement." },
  trapezius: { n: "Trapezius", L: "muscle", d: "Elevates, retracts, and rotates the scapula. Innervated by CN XI.", p: "Accessory nerve injury during posterior triangle lymph node biopsy causes shoulder droop and a weak shrug." },
  pectoralis: { n: "Pectoralis major", L: "muscle", d: "Adducts and internally rotates the arm. Innervated by the medial and lateral pectoral nerves.", p: "Poland syndrome: congenital absence of the pectoralis major, often with ipsilateral hand anomalies." },
  deltoid: { n: "Deltoid", L: "muscle", d: "Main shoulder abductor (after supraspinatus starts the first ~15°). Innervated by the axillary nerve.", p: "A common intramuscular injection site. Axillary nerve injury (surgical neck fracture, anterior dislocation) causes deltoid weakness and lateral shoulder numbness." },
  biceps: { n: "Biceps brachii", L: "muscle", d: "Flexes the elbow and is a powerful supinator. Innervated by the musculocutaneous nerve.", p: "Biceps reflex tests C5–C6. Rupture of the long head tendon produces a 'Popeye' bulge." },
  brachioradialis: { n: "Brachioradialis", L: "muscle", d: "Flexes the elbow, especially with the forearm mid-pronated. Innervated by the radial nerve (despite being a flexor).", p: "Brachioradialis reflex tests C5–C6 (with the biceps reflex)." },
  forearm_flexors: { n: "Forearm flexor group", L: "muscle", d: "Wrist and finger flexors arising from the medial epicondyle. Innervated mostly by the median nerve, plus the ulnar nerve.", p: "Medial epicondylitis ('golfer's elbow') involves the common flexor origin; lateral epicondylitis ('tennis elbow') involves the extensor origin." },
  rectus_abdominis: { n: "Rectus abdominis", L: "muscle", d: "Paired vertical muscles that flex the trunk, divided by tendinous intersections. Innervated by T7–T12.", p: "Rectus sheath hematoma (anticoagulation, coughing) causes a painful abdominal wall mass. Diastasis recti is separation along the linea alba." },
  external_oblique: { n: "External oblique", L: "muscle", d: "Outermost lateral abdominal muscle. Its aponeurosis forms the inguinal ligament (ASIS to pubic tubercle).", p: "Indirect inguinal hernias pass lateral to the inferior epigastric vessels through the deep ring; direct hernias push through Hesselbach triangle, medial to them." },
  adductors: { n: "Adductor group", L: "muscle", d: "Medial thigh muscles that pull the leg toward the midline. Innervated mainly by the obturator nerve.", p: "Adductor longus forms the medial border of the femoral triangle; groin strains often involve it." },
  vastus_lateralis: { n: "Vastus lateralis", L: "muscle", d: "Largest part of the quadriceps; extends the knee. Femoral nerve.", p: "The preferred intramuscular injection site in infants." },
  rectus_femoris: { n: "Rectus femoris", L: "muscle", d: "The only quadriceps muscle crossing the hip, so it both flexes the hip and extends the knee. Femoral nerve.", p: "The patellar reflex tests L3–L4 through the quadriceps and femoral nerve." },
  vastus_medialis: { n: "Vastus medialis", L: "muscle", d: "Teardrop-shaped quadriceps muscle above the medial knee; stabilizes the patella. Femoral nerve.", p: "Weakness contributes to lateral patellar tracking and patellofemoral pain." },
  sartorius: { n: "Sartorius", L: "muscle", d: "Longest muscle in the body; flexes, abducts, and laterally rotates the hip. Femoral nerve.", p: "Forms the lateral border of the femoral triangle (inguinal ligament above, adductor longus medially). Its tendon joins the pes anserinus with gracilis and semitendinosus." },
  tibialis_anterior: { n: "Tibialis anterior", L: "muscle", d: "Dorsiflexes and inverts the foot. Deep fibular nerve.", p: "Weakness causes foot drop. It lies in the anterior compartment, the compartment most often affected by compartment syndrome." },
  gastrocnemius: { n: "Gastrocnemius", L: "muscle", d: "Calf muscle that plantarflexes the foot via the Achilles tendon. Tibial nerve.", p: "Achilles rupture: a pop, then no plantarflexion when the calf is squeezed (positive Thompson test). Ankle reflex tests S1." },

  /* ---------- Veins ---------- */
  svc: { n: "Superior vena cava", L: "vein", d: "Drains the head, neck, arms, and upper chest into the right atrium.", p: "SVC syndrome (facial plethora, arm and face swelling) is usually caused by lung cancer (often small cell) or lymphoma." },
  brachiocephalic_v: { n: "Brachiocephalic vein", L: "vein", d: "Formed by the internal jugular and subclavian veins; the two join to form the SVC. The left is longer and crosses in front of the aortic arch branches.", p: "The left brachiocephalic vein receives the thoracic duct at the left venous angle." },
  ijv: { n: "Internal jugular vein", L: "vein", d: "Drains the brain and face; runs in the carotid sheath lateral to the common carotid artery.", p: "The right IJ is a favored central line site: a straight path to the SVC. Jugular venous pressure is estimated using the right IJ." },
  ejv: { n: "External jugular vein", L: "vein", d: "Superficial neck vein crossing the sternocleidomastoid.", p: "Visible distension suggests high right-sided pressure; it can be used for emergency IV access." },
  subclavian_v: { n: "Subclavian vein", L: "vein", d: "Continues the axillary vein beneath the clavicle.", p: "Subclavian central lines have the lowest infection risk but the highest pneumothorax risk. Effort thrombosis (Paget–Schroetter) affects young athletes." },
  axillary_v: { n: "Axillary vein", L: "vein", d: "Drains the arm; becomes the subclavian vein at the first rib.", p: "Receives the cephalic vein below the clavicle." },
  cephalic: { n: "Cephalic vein", L: "vein", d: "Superficial vein on the lateral arm; runs in the deltopectoral groove to join the axillary vein.", p: "A common site for peripheral IVs and for dialysis fistula creation (radiocephalic)." },
  basilic: { n: "Basilic vein", L: "vein", d: "Superficial vein on the medial arm; joins the brachial veins to form the axillary vein.", p: "A preferred vein for PICC line placement." },
  median_cubital: { n: "Median cubital vein", L: "vein", d: "Connects the cephalic and basilic veins in front of the elbow.", p: "The most common venipuncture site. The bicipital aponeurosis beneath it protects the brachial artery and median nerve." },
  ivc: { n: "Inferior vena cava", L: "vein", d: "Drains the body below the diaphragm into the right atrium; passes the diaphragm at T8.", p: "An IVC filter is an option for acute VTE when anticoagulation is contraindicated. Renal cell carcinoma can grow into the renal vein and IVC." },
  hepatic_v: { n: "Hepatic veins", L: "vein", d: "Drain the liver directly into the IVC.", p: "Budd–Chiari syndrome (hepatic vein thrombosis, e.g., with polycythemia vera or other hypercoagulable states) causes painful hepatomegaly and ascites." },
  portal_v: { n: "Hepatic portal vein", L: "vein", d: "Formed behind the pancreatic neck by the splenic vein and superior mesenteric vein; carries gut blood to the liver.", p: "Portal hypertension opens portosystemic shunts: esophageal varices (left gastric ↔ esophageal), caput medusae (paraumbilical ↔ epigastric), and rectal varices. TIPS connects the portal vein to a hepatic vein." },
  splenic_v: { n: "Splenic vein", L: "vein", d: "Runs behind the pancreas from the spleen to join the SMV.", p: "Splenic vein thrombosis (often from pancreatitis) causes isolated gastric varices via the short gastric veins." },
  smv: { n: "Superior mesenteric vein", L: "vein", d: "Drains the small intestine and right colon; lies to the right of the SMA.", p: "Mesenteric venous thrombosis is a cause of bowel ischemia in hypercoagulable states." },
  renal_v: { n: "Renal vein", L: "vein", d: "Drains each kidney into the IVC. The left is longer and receives the left gonadal and left adrenal veins.", p: "Left varicoceles are more common because the left gonadal vein enters the left renal vein at a right angle." },
  common_iliac_v: { n: "Common iliac vein", L: "vein", d: "Formed by the internal and external iliac veins; the two join at about L5 to form the IVC.", p: "May–Thurner syndrome: the right common iliac artery compresses the left common iliac vein, causing left-leg DVT." },
  femoral_v: { n: "Femoral vein", L: "vein", d: "Deep vein of the thigh, medial to the femoral artery (NAVeL: nerve, artery, vein, empty space, lymphatics, lateral to medial).", p: "Proximal DVT (femoral or popliteal) carries a higher risk of pulmonary embolism than calf DVT." },
  popliteal_v: { n: "Popliteal vein", L: "vein", d: "Deep vein behind the knee (dashed: on the back of the body).", p: "Included in compression ultrasound for DVT. Receives the small saphenous vein.", post: true },
  great_saphenous: { n: "Great saphenous vein", L: "vein", d: "The body's longest vein: from in front of the medial malleolus up the medial leg to the femoral vein at the saphenofemoral junction.", p: "Harvested for coronary bypass grafts. The saphenous nerve runs with it below the knee." },
  small_saphenous: { n: "Small saphenous vein", L: "vein", d: "Runs from behind the lateral malleolus up the back of the calf to the popliteal vein (dashed: on the back).", p: "The sural nerve accompanies it, a common nerve biopsy site.", post: true },

  /* ---------- Arteries ---------- */
  aorta: { n: "Aorta", L: "artery", d: "Ascending aorta, arch, descending thoracic, and abdominal aorta, which bifurcates at about L4.", p: "Arch branches: brachiocephalic trunk, left common carotid, left subclavian. USPSTF recommends one-time AAA ultrasound screening for men 65–75 who have ever smoked. Stanford type A dissection (ascending) is a surgical emergency." },
  coronary: { n: "Coronary arteries", L: "artery", d: "Right coronary artery (RCA), left anterior descending (LAD), and left circumflex. Most people are right dominant (posterior descending artery from the RCA).", p: "The LAD is the most commonly occluded. Inferior MI usually means the RCA, which also supplies the right ventricle and often the AV node (bradycardia, heart block)." },
  brachiocephalic_a: { n: "Brachiocephalic trunk", L: "artery", d: "First arch branch; divides into the right subclavian and right common carotid arteries.", p: "Tracheo-innominate fistula after tracheostomy can cause massive bleeding." },
  common_carotid: { n: "Common carotid artery", L: "artery", d: "Ascends in the carotid sheath and splits at the upper border of the thyroid cartilage (C3–C4).", p: "The carotid sinus at the bifurcation senses pressure (afferent CN IX); carotid massage slows the heart via the vagus." },
  internal_carotid: { n: "Internal carotid artery", L: "artery", d: "No branches in the neck; enters the skull to supply the eye (ophthalmic artery) and most of the cerebral hemisphere.", p: "Amaurosis fugax (transient monocular vision loss) is a retinal TIA, usually from an ipsilateral carotid plaque." },
  external_carotid: { n: "External carotid artery", L: "artery", d: "Supplies the face, scalp, and neck: superior thyroid, ascending pharyngeal, lingual, facial, occipital, posterior auricular, maxillary, superficial temporal.", p: "The middle meningeal artery (from the maxillary) causes epidural hematomas. The superficial temporal artery is biopsied for giant cell arteritis." },
  vertebral: { n: "Vertebral artery", L: "artery", d: "Arises from the subclavian, runs up through the cervical transverse foramina, and joins its partner to form the basilar artery.", p: "Subclavian steal: proximal subclavian stenosis reverses vertebral flow, causing arm claudication and dizziness with arm use, plus a blood pressure difference between arms." },
  subclavian_a: { n: "Subclavian artery", L: "artery", d: "Right from the brachiocephalic trunk, left directly from the arch; becomes the axillary artery at the first rib.", p: "Thoracic outlet syndrome (e.g., cervical rib) can compress the subclavian artery and brachial plexus." },
  axillary_a: { n: "Axillary artery", L: "artery", d: "Runs through the axilla; divided into three parts by pectoralis minor.", p: "Can be injured with anterior shoulder dislocation, along with the axillary nerve." },
  brachial: { n: "Brachial artery", L: "artery", d: "Main artery of the arm; divides into radial and ulnar arteries in the cubital fossa.", p: "Supracondylar humerus fractures in children can injure it; untreated ischemia leads to Volkmann contracture." },
  radial_a: { n: "Radial artery", L: "artery", d: "Lateral forearm artery; its pulse is felt at the wrist and in the anatomical snuffbox.", p: "Usual site for arterial blood gases and arterial lines; check ulnar collateral flow first." },
  ulnar_a: { n: "Ulnar artery", L: "artery", d: "Medial forearm artery; passes through the Guyon canal with the ulnar nerve.", p: "Hypothenar hammer syndrome: repetitive palm trauma causes ulnar artery thrombosis and finger ischemia." },
  palmar_arch: { n: "Palmar arches", L: "artery", d: "Superficial arch (mainly ulnar) and deep arch (mainly radial) give the fingers dual supply.", p: "This dual supply is why radial artery cannulation is usually tolerated." },
  celiac: { n: "Celiac trunk", L: "artery", d: "Arises at T12; supplies the foregut through the left gastric, splenic, and common hepatic arteries.", p: "Median arcuate ligament syndrome: compression of the celiac trunk causes postprandial pain and weight loss." },
  sma: { n: "Superior mesenteric artery", L: "artery", d: "Arises at L1; supplies the midgut, from the distal duodenum to the proximal two-thirds of the transverse colon.", p: "Acute mesenteric ischemia (often an embolus in atrial fibrillation) causes pain out of proportion to exam. SMA syndrome: rapid weight loss lets the SMA compress the 3rd part of the duodenum." },
  renal_a: { n: "Renal artery", L: "artery", d: "Arises at about L1–L2 and enters the kidney at the hilum.", p: "Renovascular hypertension: fibromuscular dysplasia in young women ('string of beads'), atherosclerosis in older adults. ACE inhibitors can precipitate AKI with bilateral stenosis." },
  ima: { n: "Inferior mesenteric artery", L: "artery", d: "Arises at L3; supplies the hindgut, from the distal transverse colon to the upper rectum.", p: "A horseshoe kidney is trapped beneath the IMA during ascent." },
  common_iliac_a: { n: "Common iliac artery", L: "artery", d: "Formed at the aortic bifurcation (about L4, near the umbilicus); divides into internal and external iliac arteries.", p: "Aortoiliac occlusive disease (Leriche syndrome): buttock claudication, absent femoral pulses, and erectile dysfunction." },
  internal_iliac: { n: "Internal iliac artery", L: "artery", d: "Supplies the pelvic organs, perineum, and gluteal region.", p: "Its branches are embolized to control bleeding from pelvic fractures or postpartum hemorrhage." },
  external_iliac: { n: "External iliac artery", L: "artery", d: "Becomes the femoral artery as it passes under the inguinal ligament.", p: "Gives off the inferior epigastric artery, the landmark separating direct and indirect inguinal hernias." },
  femoral_a: { n: "Femoral artery", L: "artery", d: "Main artery of the thigh, in the femoral triangle lateral to the femoral vein.", p: "A common access site for cardiac catheterization; complications include pseudoaneurysm and retroperitoneal bleeding." },
  popliteal_a: { n: "Popliteal artery", L: "artery", d: "Deep artery behind the knee (dashed: on the back).", p: "Knee dislocation can tear it; check the ankle-brachial index and image if abnormal. Popliteal aneurysm is the most common peripheral aneurysm and is often bilateral.", post: true },
  anterior_tibial: { n: "Anterior tibial artery", L: "artery", d: "Runs in the anterior compartment and becomes the dorsalis pedis on top of the foot.", p: "The dorsalis pedis pulse is felt lateral to the extensor hallucis longus tendon." },
  posterior_tibial: { n: "Posterior tibial artery", L: "artery", d: "Runs in the deep posterior compartment (dashed: on the back).", p: "Its pulse is felt behind the medial malleolus, in the tarsal tunnel with the tibial nerve.", post: true },

  /* ---------- Nerves ---------- */
  spinal_cord: { n: "Spinal cord and cauda equina", L: "nerve", d: "Runs within the vertebral canal and ends at the conus medullaris (L1–L2 in adults); nerve roots continue below as the cauda equina.", p: "Brown-Séquard (hemisection): ipsilateral weakness and loss of proprioception, contralateral loss of pain and temperature. Anterior cord syndrome spares proprioception. Central cord syndrome (elderly, hyperextension) weakens the arms more than the legs." },
  vagus: { n: "Vagus nerve (CN X)", L: "nerve", d: "Descends in the carotid sheath to supply the larynx, pharynx, heart, lungs, and gut to the splenic flexure.", p: "Left recurrent laryngeal nerve hooks under the aortic arch, the right under the right subclavian artery." },
  rln_left: { n: "Left recurrent laryngeal nerve", L: "nerve", d: "Branch of the left vagus that loops under the aortic arch and climbs back up to supply the larynx.", p: "Hoarseness can be caused by an aortic arch aneurysm, an enlarged left atrium (Ortner syndrome), lung cancer, or thyroid surgery." },
  phrenic: { n: "Phrenic nerve", L: "nerve", d: "C3–C5 ('keep the diaphragm alive'); runs down the mediastinum to supply the diaphragm.", p: "Injury or tumor invasion elevates the hemidiaphragm on x-ray. Diaphragmatic irritation refers pain to the shoulder through these roots." },
  brachial_plexus: { n: "Brachial plexus", L: "nerve", d: "C5–T1 roots → trunks → divisions → cords → branches ('Randy Travis Drinks Cold Beer').", p: "Erb palsy (C5–C6, lateral neck traction): 'waiter's tip' posture. Klumpke palsy (C8–T1, arm pulled upward): claw hand, sometimes with Horner syndrome." },
  axillary_n: { n: "Axillary nerve", L: "nerve", d: "C5–C6; winds around the surgical neck of the humerus to supply the deltoid and teres minor.", p: "Injured by surgical neck fractures and anterior shoulder dislocations: weak abduction and numbness over the lateral shoulder." },
  musculocutaneous: { n: "Musculocutaneous nerve", L: "nerve", d: "C5–C7; supplies biceps, brachialis, and coracobrachialis, then becomes the lateral cutaneous nerve of the forearm.", p: "Injury causes weak elbow flexion and supination with numbness of the lateral forearm." },
  median_n: { n: "Median nerve", L: "nerve", d: "C5–T1 (mainly C6–T1); runs with the brachial artery, through the forearm, and under the flexor retinaculum in the carpal tunnel.", p: "Carpal tunnel syndrome: numbness of the lateral 3½ digits and thenar atrophy, with sensation over the thenar eminence spared (palmar cutaneous branch runs above the tunnel). Proximal lesions cause the 'hand of benediction' when making a fist." },
  ulnar_n: { n: "Ulnar nerve", L: "nerve", d: "C8–T1; passes behind the medial epicondyle and through the Guyon canal to supply most intrinsic hand muscles.", p: "Damage causes clawing of the ring and little fingers (more pronounced with distal lesions, the 'ulnar paradox'). Hook of hamate fractures and cycling can compress it in the Guyon canal." },
  radial_n: { n: "Radial nerve", L: "nerve", d: "C5–T1; spirals in the radial groove on the back of the humerus (dashed), then supplies the extensors ('BEST': brachioradialis, extensors, supinator, triceps).", p: "Wrist drop from midshaft humerus fracture, 'Saturday night palsy' (arm over a chair), or improper crutch use." },
  long_thoracic: { n: "Long thoracic nerve", L: "nerve", d: "C5–C7; runs down the lateral chest wall to the serratus anterior.", p: "Injury (often during axillary node dissection) causes a winged scapula." },
  intercostal: { n: "Intercostal nerves", L: "nerve", d: "Ventral rami of T1–T11, running under each rib below the vein and artery (VAN, top to bottom).", p: "Herpes zoster most often affects a thoracic dermatome, producing a band-like rash that stops at the midline." },
  femoral_n: { n: "Femoral nerve", L: "nerve", d: "L2–L4; passes under the inguinal ligament lateral to the femoral artery to supply the quadriceps and anterior thigh skin.", p: "Injury causes weak knee extension and a diminished patellar reflex." },
  saphenous_n: { n: "Saphenous nerve", L: "nerve", d: "Sensory branch of the femoral nerve to the medial leg and foot; travels with the great saphenous vein.", p: "Can be injured during vein harvest or varicose vein surgery, causing medial leg numbness." },
  obturator_n: { n: "Obturator nerve", L: "nerve", d: "L2–L4; passes through the obturator foramen to the adductor muscles.", p: "Injured in pelvic surgery or anterior hip dislocation: weak adduction and medial thigh numbness." },
  lfcn: { n: "Lateral femoral cutaneous nerve", L: "nerve", d: "L2–L3; purely sensory to the lateral thigh, passing near the ASIS.", p: "Meralgia paresthetica: burning numbness of the lateral thigh from compression (tight belts, obesity, pregnancy)." },
  sciatic: { n: "Sciatic nerve", L: "nerve", d: "L4–S3; the largest nerve, running down the back of the thigh (dashed) and dividing into tibial and common fibular nerves above the knee.", p: "At risk with posterior hip dislocation. Give gluteal injections in the upper outer quadrant to avoid it.", post: true },
  tibial_n: { n: "Tibial nerve", L: "nerve", d: "Supplies the posterior leg (plantarflexion, inversion) and the sole; passes behind the medial malleolus (dashed: on the back).", p: "Tarsal tunnel syndrome causes burning pain and numbness in the sole.", post: true },
  common_fibular: { n: "Common fibular (peroneal) nerve", L: "nerve", d: "Wraps around the fibular neck, then divides into deep (dorsiflexion, first web space) and superficial (eversion, dorsum of foot) branches.", p: "Fibular neck fracture, tight casts, or prolonged leg crossing cause foot drop, steppage gait, and loss of eversion." },

  /* ---------- Lymphatics ---------- */
  thymus: { n: "Thymus", L: "lymph", d: "Site of T-cell maturation in the anterior mediastinum; large in infants and involutes with age.", p: "Thymoma is associated with myasthenia gravis. DiGeorge syndrome (22q11.2 deletion) causes thymic aplasia and T-cell deficiency." },
  lymph_vessels: { n: "Lymphatic vessels", L: "lymph", d: "Return interstitial fluid to the blood via lymph nodes.", p: "Lymphedema follows node removal or radiation (e.g., axillary dissection for breast cancer); filariasis causes it worldwide." },
  thoracic_duct: { n: "Thoracic duct", L: "lymph", d: "Begins at the cisterna chyli (about L1–L2) and empties into the left venous angle (left IJ–subclavian junction). Drains everything except the right upper body.", p: "Injury causes chylothorax: milky pleural fluid with triglycerides above 110 mg/dL." },
  right_lymphatic_duct: { n: "Right lymphatic duct", L: "lymph", d: "Drains the right side of the head, neck, chest, and right arm into the right venous angle.", p: "Explains why left supraclavicular nodes signal abdominal disease, while right supraclavicular nodes point to chest or esophageal disease." },
  cervical_nodes: { n: "Cervical lymph nodes", L: "lymph", d: "Chains along the internal jugular vein draining the head and neck.", p: "Firm, fixed, painless nodes in an adult who smokes or drinks should raise concern for head and neck squamous cell carcinoma." },
  virchow_node: { n: "Left supraclavicular (Virchow) node", L: "lymph", d: "Receives lymph near the thoracic duct's entry into the left venous angle.", p: "An enlarged Virchow node suggests an abdominal malignancy, classically gastric cancer." },
  axillary_nodes: { n: "Axillary lymph nodes", L: "lymph", d: "Drain the arm, the chest wall, and most (~75%) of the breast.", p: "Sentinel lymph node biopsy stages breast cancer; full axillary dissection risks lymphedema and long thoracic nerve injury." },
  para_aortic_nodes: { n: "Para-aortic lymph nodes", L: "lymph", d: "Along the abdominal aorta; drain the kidneys, adrenals, testes, and ovaries.", p: "Testicular cancer spreads to para-aortic nodes, not inguinal nodes, because the testis develops in the abdomen." },
  inguinal_nodes: { n: "Inguinal lymph nodes", L: "lymph", d: "Superficial nodes drain the leg, lower abdominal wall, perineum, scrotal skin, vulva, and anal canal below the pectinate line.", p: "Inguinal lymphadenopathy with a genital ulcer suggests syphilis, herpes, chancroid, or lymphogranuloma venereum." },
};

/* ---------- Cranial nerves ---------- */
const CN = [
  { num: "I", name: "Olfactory", type: "S", exit: "Cribriform plate (ethmoid bone)", from: "Olfactory bulb (forebrain)",
    fn: "Smell.", test: "Each nostril separately with a familiar, non-irritating odor (coffee, soap), eyes closed.",
    lesion: "Loss of smell (anosmia).",
    pearl: "The only sensory pathway that reaches cortex without relaying in the thalamus. Anterior skull base fracture → anosmia plus CSF rhinorrhea. Kallmann syndrome = anosmia + hypogonadotropic hypogonadism. Smell loss can precede Parkinson and Alzheimer disease." },
  { num: "II", name: "Optic", type: "S", exit: "Optic canal (lesser wing of sphenoid)", from: "Retina → optic chiasm (forebrain)",
    fn: "Vision; afferent limb of the pupillary light reflex.", test: "Visual acuity, visual fields by confrontation, fundoscopy, pupillary light reflex.",
    lesion: "Monocular vision loss (nerve), bitemporal hemianopia (chiasm), contralateral homonymous hemianopia (tract or beyond).",
    pearl: "Technically a CNS tract myelinated by oligodendrocytes, which is why optic neuritis occurs in multiple sclerosis. Swinging-flashlight test reveals a relative afferent pupillary defect (Marcus Gunn pupil). Pituitary adenoma compresses the chiasm." },
  { num: "III", name: "Oculomotor", type: "M", exit: "Superior orbital fissure", from: "Midbrain (interpeduncular fossa); Edinger–Westphal nucleus for parasympathetics",
    fn: "Superior, inferior, and medial rectus; inferior oblique; levator palpebrae superioris. Parasympathetic: pupillary constriction and accommodation (via ciliary ganglion).",
    test: "Eye movements (H pattern), eyelid elevation, pupil size and light response.",
    lesion: "Eye 'down and out,' ptosis, dilated nonreactive pupil.",
    pearl: "Compression (posterior communicating artery aneurysm, uncal herniation) affects the pupil early because parasympathetic fibers run on the nerve's surface. Ischemic palsy (diabetes) typically spares the pupil." },
  { num: "IV", name: "Trochlear", type: "M", exit: "Superior orbital fissure", from: "Midbrain (exits dorsally)",
    fn: "Superior oblique: depresses the eye (especially when adducted) and intorts it.",
    test: "Ask the patient to look down and in (toward the nose), as when reading or walking downstairs.",
    lesion: "Vertical diplopia, worse looking down; head tilts away from the affected side to compensate.",
    pearl: "The only cranial nerve that exits the back of the brainstem and the only one that crosses before exiting. Longest intracranial course and thinnest, so it is vulnerable to head trauma." },
  { num: "V", name: "Trigeminal", type: "B", exit: "V1: superior orbital fissure; V2: foramen rotundum; V3: foramen ovale ('Standing Room Only')", from: "Pons (lateral)",
    fn: "Sensation of the face, cornea, mouth, and anterior two-thirds of the tongue (general sensation). V3 motor: muscles of mastication (masseter, temporalis, pterygoids), plus tensor tympani, tensor veli palatini, mylohyoid, anterior digastric.",
    test: "Light touch in all three divisions, corneal reflex (afferent V1, efferent VII), jaw clench, jaw jerk.",
    lesion: "Facial numbness; the jaw deviates toward the weak side (unopposed lateral pterygoid).",
    pearl: "Trigeminal neuralgia: brief electric facial pain; first-line treatment is carbamazepine. Herpes zoster ophthalmicus with vesicles on the nose tip (Hutchinson sign) predicts eye involvement." },
  { num: "VI", name: "Abducens", type: "M", exit: "Superior orbital fissure", from: "Pons (nucleus); exits at the pontomedullary junction",
    fn: "Lateral rectus: abducts the eye.", test: "Look laterally toward each side.",
    lesion: "Horizontal diplopia worse looking toward the affected side and at distance; eye turned inward at rest.",
    pearl: "Long course along the clivus makes it a classic 'false localizing sign' of raised intracranial pressure. It runs freely inside the cavernous sinus next to the internal carotid, so it is often the first nerve affected by cavernous sinus thrombosis or carotid aneurysm." },
  { num: "VII", name: "Facial", type: "B", exit: "Internal acoustic meatus → facial canal → stylomastoid foramen", from: "Pons (cerebellopontine angle)",
    fn: "Muscles of facial expression, stapedius, stylohyoid, posterior digastric. Taste from the anterior two-thirds of the tongue (chorda tympani). Parasympathetic to lacrimal, submandibular, and sublingual glands.",
    test: "Raise eyebrows, close eyes tightly, show teeth, puff cheeks; taste on the anterior tongue.",
    lesion: "Lower motor neuron lesion (Bell palsy): whole ipsilateral face, including the forehead. Upper motor neuron lesion (stroke): lower face only, forehead spared.",
    pearl: "The forehead is spared in central lesions because it receives cortical input from both hemispheres. Bell palsy: start oral corticosteroids within 72 hours. Hyperacusis comes from stapedius paralysis. Lyme disease can cause bilateral facial palsy." },
  { num: "VIII", name: "Vestibulocochlear", type: "S", exit: "Internal acoustic meatus (stays within the temporal bone)", from: "Pontomedullary junction (cerebellopontine angle)",
    fn: "Hearing (cochlear division) and balance (vestibular division).",
    test: "Whispered voice, Weber and Rinne tests; head impulse test and Dix–Hallpike for vertigo.",
    lesion: "Sensorineural hearing loss, tinnitus, vertigo, nystagmus.",
    pearl: "Vestibular schwannoma at the cerebellopontine angle → unilateral sensorineural hearing loss and tinnitus (bilateral in NF2). Weber lateralizes to the good ear in sensorineural loss and to the affected ear in conductive loss." },
  { num: "IX", name: "Glossopharyngeal", type: "B", exit: "Jugular foramen", from: "Medulla (postolivary sulcus)",
    fn: "Motor to stylopharyngeus only. Taste and sensation from the posterior third of the tongue; sensation from the pharynx and middle ear. Carotid sinus and body afferents. Parasympathetic to the parotid gland (via otic ganglion).",
    test: "Gag reflex (afferent limb), taste on the posterior tongue.",
    lesion: "Loss of gag sensation, loss of posterior tongue taste, mild dysphagia.",
    pearl: "Carotid sinus massage: afferent IX, efferent X → slowed heart rate. Glossopharyngeal neuralgia causes stabbing throat and ear pain triggered by swallowing." },
  { num: "X", name: "Vagus", type: "B", exit: "Jugular foramen", from: "Medulla (postolivary sulcus); nucleus ambiguus and dorsal motor nucleus",
    fn: "Motor to the palate, pharynx, and larynx (except stylopharyngeus and tensor veli palatini). Parasympathetic to thoracic and abdominal organs up to the splenic flexure. Sensation from the larynx, pharynx, external ear canal, and viscera.",
    test: "Say 'ah' (watch the uvula), voice quality, swallow, gag reflex (efferent limb).",
    lesion: "Uvula deviates away from the affected side; hoarseness; dysphagia.",
    pearl: "The left recurrent laryngeal nerve loops under the aortic arch, the right under the subclavian artery, so mediastinal disease causes hoarseness. Its auricular branch explains coughing during ear canal exams." },
  { num: "XI", name: "Accessory", type: "M", exit: "Jugular foramen (spinal roots ascend through the foramen magnum first)", from: "Upper cervical spinal cord",
    fn: "Sternocleidomastoid (turns the head to the opposite side) and trapezius (shrugs the shoulder).",
    test: "Shrug against resistance; turn the head against resistance.",
    lesion: "Shoulder droop and weak shrug on the same side; weak head turning toward the opposite side.",
    pearl: "Vulnerable in the posterior triangle of the neck, classically injured during lymph node biopsy." },
  { num: "XII", name: "Hypoglossal", type: "M", exit: "Hypoglossal canal (occipital bone)", from: "Medulla (preolivary sulcus, between pyramid and olive)",
    fn: "All intrinsic and extrinsic tongue muscles except palatoglossus (supplied by X).",
    test: "Stick out the tongue; push it into each cheek.",
    lesion: "Tongue deviates toward the affected side, with atrophy and fasciculations in lower motor neuron lesions.",
    pearl: "Medial medullary syndrome: ipsilateral tongue deviation with contralateral hemiparesis and contralateral loss of proprioception and vibration." },
];
